9	std::string encoded_name(const std::string& name)
10	{
11	    const bool plain = name.compare(0, 9, "=?base64?") != 0 &&
12	        std::all_of(name.begin(), name.end(), [](unsigned char c) { return c >= 0x20 && c <= 0x7e; });
13	    if (plain) return name;
14	    constexpr char alphabet[] = "REDACTED/";
15	    std::string out = "=?base64?";
16	    for (std::size_t i = 0; i < name.size(); i += 3) {
17	        unsigned bits = unsigned(static_cast<unsigned char>(name[i])) << 16;
18	        if (i + 1 < name.size()) bits |= unsigned(static_cast<unsigned char>(name[i + 1])) << 8;
19	        if (i + 2 < name.size()) bits |= static_cast<unsigned char>(name[i + 2]);
20	        out += alphabet[(bits >> 18) & 63]; out += alphabet[(bits >> 12) & 63];
21	        out += i + 1 < name.size() ? alphabet[(bits >> 6) & 63] : '=';
22	        out += i + 2 < name.size() ? alphabet[bits & 63] : '=';
23	    }
24	    return out + "?=";
25	}
