62	void HttpExchange::start()
63	{
64	    m_deadline.expires_after(m_timeout);
65	    m_deadline.async_wait([self = shared_from_this()](Error error) {
66	        if (!error) self->fail("The local MCP request timed out.");
67	    });
68	    m_socket.async_connect({net::ip::make_address_v4("127.0.0.1"), m_port}, [self = shared_from_this()](Error error) {
69	        if (self->m_closed) return;
70	        if (error) { self->fail(error.message()); return; }
71	        http::async_write(self->m_socket, self->m_request, [self](Error error, std::size_t) {
72	            if (self->m_closed) return;
73	            if (error) { self->fail(error.message()); return; }
74	            http::async_read_header(self->m_socket, self->m_buffer, self->m_parser, [self](Error error, std::size_t) {
75	                if (self->m_closed) return;
76	                if (error) { self->fail(error.message()); return; }
77	                const auto media = self->m_parser.get()[http::field::content_type];
78	                self->m_streaming = media.substr(0, 17) == "text/event-stream";
79	                if (!self->m_streaming && media.substr(0, 16) != "application/json") {
80	                    self->fail("The local endpoint did not return MCP JSON or SSE."); return;
81	                }
82	                self->read_body();
83	            });
84	        });
85	    });
86	}
