88	void HttpExchange::read_body()
89	{
90	    if (m_closed) return;
91	    m_parser.get().body().data = m_chunk.data();
92	    m_parser.get().body().size = m_chunk.size();
93	    http::async_read_some(m_socket, m_buffer, m_parser, [self = shared_from_this()](Error error, std::size_t) {
94	        if (self->m_closed) return;
95	        const auto received = self->m_chunk.size() - self->m_parser.get().body().size;
96	        self->consume(std::string_view(self->m_chunk.data(), received));
97	        if (self->m_closed) return;
98	        if (error == http::error::need_buffer) error.clear();
99	        if (error) { self->fail(error.message()); return; }
100	        if (self->m_parser.is_done()) {
101	            if (!self->m_streaming) self->deliver(self->m_body);
102	            if (!self->m_closed) self->fail("MCP response ended without a terminal result.");
103	        } else self->read_body();
104	    });
105	}
