107	void HttpExchange::consume(std::string_view bytes)
108	{
109	    m_body.append(bytes);
110	    if (m_body.size() + m_event.size() > 256 * 1024) { fail("MCP response exceeds the limit."); return; }
111	    if (!m_streaming) return;
112	    for (auto end = m_body.find('\n'); end != std::string::npos; end = m_body.find('\n')) {
113	        std::string line = m_body.substr(0, end);
114	        m_body.erase(0, end + 1);
115	        if (!line.empty() && line.back() == '\r') line.pop_back();
116	        if (line.empty() && !m_event.empty()) {
117	            const auto event = std::move(m_event); m_event.clear();
118	            deliver(event);
119	            if (m_closed) return;
120	        } else if (line.compare(0, 5, "data:") == 0) {
121	            if (!m_event.empty()) m_event += '\n';
122	            m_event += line.substr(line.size() > 5 && line[5] == ' ' ? 6 : 5);
123	        }
124	    }
125	}
