127	void HttpExchange::deliver(const std::string& bytes)
128	{
129	    const auto value = json::parse(bytes, nullptr, false);
130	    if (!value.is_object() || value.value("jsonrpc", json()) != "2.0") { fail("Invalid MCP response envelope."); return; }
131	    const bool terminal = value.contains("result") || value.contains("error");
132	    if (terminal) {
133	        if (value.contains("result") == value.contains("error") ||
134	            (value.contains("result") && !value["result"].is_object()) ||
135	            (value.contains("error") && (!value["error"].is_object() ||
136	                !value["error"].value("code", json()).is_number_integer() || !value["error"].value("message", json()).is_string()))) {
137	            fail("Invalid MCP result or error envelope."); return;
138	        }
139	    } else if (value.contains("id") || !value.value("method", json()).is_string() ||
140	               !value.value("params", json::object()).is_object()) {
141	        fail("Invalid MCP notification envelope."); return;
142	    }
143	    if (terminal && value.value("id", json()) != m_id) { fail("MCP response ID does not match the request."); return; }
144	    if (terminal) cancel();
145	    m_message(value, terminal);
146	}
