148	void HttpExchange::cancel()
149	{
150	    if (m_closed) return;
151	    m_closed = true;
152	    m_deadline.cancel();
153	    Error ignored;
154	    m_socket.shutdown(net::ip::tcp::socket::shutdown_both, ignored);
155	    m_socket.close(ignored);
156	}
