190	    Error error;
191	    acceptor.bind({net::ip::make_address_v4("127.0.0.1"), options.port}, error);
192	    if (error == net::error::address_in_use && options.port != 0 && options.fallback_to_ephemeral)
193	        acceptor.bind({net::ip::make_address_v4("127.0.0.1"), 0}, error);
194	    if (error) throw boost::system::system_error(error, "Could not bind the local MCP listener");
195	    acceptor.listen(int(options.max_connections));
196	    port = acceptor.local_endpoint().port();
197	    origin = "http://127.0.0.1:" + std::to_string(port);
198	    url = origin + "/mcp";
199	    accept();
200	    worker = std::thread([this] { io.run(); });
