203	void McpServer::Impl::accept()
204	{
205	    acceptor.async_accept([this](Error error, tcp::socket socket) {
206	        if (stopping) return;
207	        if (!error && connections.size() < options.max_connections) {
208	            const auto id = next_connection++;
209	            auto connection = std::make_shared<Connection>(*this, std::move(socket), id);
210	            connections.emplace(id, connection);
211	            connection->start();
212	        }
213	        // Excess connections are closed without allocating a request/parser.
214	        if (error != net::error::operation_aborted) accept();
215	    });
216	}
