218	void McpServer::Impl::stop()
219	{
220	    if (!worker.joinable()) return;
221	    net::post(io, [this] {
222	        stopping = true;
223	        Error ignored;
224	        acceptor.close(ignored);
225	        while (!connections.empty()) {
226	            auto connection = connections.begin()->second;
227	            connection->close();
228	        }
229	    });
230	    worker.join();
231	}
